#Requires -Version 7.0
<#
.SYNOPSIS
Receipt-only hostile probes, using unchanged real workflow, cache, builder, and shim functions.
.DESCRIPTION
Only the immediate transport is doubled. Files remain below docs/receipts/hv.+The transport captures actual serialized payloads; it does not prove server durability.
#>
$ErrorActionPreference = 'Stop'
$repo = 'F:\GitHub\McpServer\.worktrees\sessionlife-p2-contracts-5cb2'
$receiptRoot = Join-Path $repo 'docs/receipts/hv'
$work = Join-Path $receiptRoot ('20261003T011854Z-probe-fixtures-' + [guid]::NewGuid().ToString('N'))
[void][IO.Directory]::CreateDirectory($work)
$env:MCP_PLUGIN_HOST = 'codex'
$env:MCP_AGENT_NAME = 'Codex'
$env:MCP_PLUGIN_PERSIST_LOG = $null
. (Join-Path $repo 'plugins/core/lib-ps/repl-invoke.ps1')
$result = [ordered]@{timestampUtc=[DateTimeOffset]::UtcNow.ToString('o');tipSha=(& git -C $repo rev-parse HEAD);work=$work;boundary='Actual production functions and YAML IO, immediate transport double only; no server persistence claim';cases=@()}
function New-HvCase {
    param([string]$Name,[switch]$NoTurn,[switch]$NoMetadata,[switch]$Persisted,[switch]$Degraded,[switch]$NoSessionBinding)
    $script:caseRoot = Join-Path $work $Name
    $script:cache = Join-Path $script:caseRoot 'cache'
    $script:ws = Join-Path $script:caseRoot 'ws'
    $script:queue = Join-Path $script:caseRoot 'failsafe'
    foreach($dir in @($script:cache,$script:ws,$script:queue)){[void][IO.Directory]::CreateDirectory($dir)}
    $env:MCP_CACHE_DIR_OVERRIDE=$script:cache
    $env:MCP_WORKSPACE_PATH=$script:ws
    $env:MCPSERVER_WORKSPACE_PATH=$script:ws
    $env:MCPSERVER_FAILSAFE_DIR=$script:queue
    $env:MCP_PLUGIN_ROOT=Join-Path $repo 'plugins/core'
    Set-Location $script:ws
    Write-McpYamlObject -Path (Join-Path $script:ws 'AGENTS-README-FIRST.yaml') -Document ([ordered]@{workspacePath=$script:ws;apiKey='isolated-hv-fixture'})
    $snap=Get-MarkerFileSnapshot -StartDir $script:ws
    Write-McpYamlObject -Path (Join-Path $script:cache 'session-state.yaml') -Document ([ordered]@{status='verified';sessionId='Codex-20260930T000000Z-sessionA';agent='Codex';title='original session';markerFilePath=$snap.markerFilePath;markerLastWriteUtc=$snap.markerLastWriteUtc})
    if(-not $NoTurn){
        $turn=[ordered]@{turnRequestId='req-R';sessionId='Codex-20260930T000000Z-sessionA';status='in_progress';queryText='original query';queryTitle='original title';openedAt=[DateTimeOffset]::UtcNow.ToString('o');auditActions=3;auditDialog=2;lastBuildStatus='succeeded';markerFilePath=$snap.markerFilePath;markerLastWriteUtc=$snap.markerLastWriteUtc}
        if(-not $NoMetadata){$turn.planFile='docs/plans/p2.md';$turn.todoId='BUG-TRIAGE-246'}
        if($Persisted){$turn.persisted=$true}
        if($Degraded){$turn.degraded=$true}
        if($NoSessionBinding){$turn.Remove('sessionId')}
        Write-McpYamlObject -Path (Join-Path $script:cache 'current-turn.yaml') -Document $turn
    }
    $script:calls=@();$script:mode='primary';$script:serverTurnExists=$false
    $script:LastReplPersistenceDetails=$null
}
function Invoke-ReplRaw {
    param([string]$Method,[string]$ParamsYaml)
    $params=Convert-ReplParamsYamlToObject -ParamsYaml $ParamsYaml
    $script:calls += [ordered]@{method=$Method;params=$params}
    if($script:mode -eq 'unavailable'){return @{Success=$false;Output='HTTP 503 backend_unavailable';Error='fixture outage'}}
    if($script:mode -eq 'recovery'){
        if($Method -eq 'client.SessionLog.AppendDialogAsync' -and -not $script:serverTurnExists){return @{Success=$false;Output='HTTP 404 not_found';Error='turn missing'}}
        if($Method -eq 'client.SessionLog.SubmitAsync'){
            $turn=$params.sessionLog.turns[0]
            if([string]::IsNullOrWhiteSpace($turn.planFile) -or [string]::IsNullOrWhiteSpace($turn.todoId)){return @{Success=$false;Output='HTTP 400 missing first-persist planFile/todoId';Error='metadata required'}}
            $script:serverTurnExists=$true
        }
    }
    if($Method -in @('client.SessionLog.AppendDialogAsync','client.SessionLog.SetTurnTitleAsync')){return @{Success=$true;Output=(ConvertTo-Yaml -Data @{payload=@{result=@{sessionId=$params.sessionId;requestId=$params.requestId;totalDialogCount=3;retitled=$true}}});Error=''}}
    if($Method -eq 'client.SessionLog.QueryAsync'){return @{Success=$true;Output=(ConvertTo-Yaml -Data @{payload=@{result=@{items=@()}}});Error=''}}
    return @{Success=$true;Output=(ConvertTo-Yaml -Data @{payload=@{result=@{persisted=$true;degraded=$false}}});Error=''}
}
function Add-HvCase {
    param([string]$Name,$Return,$Extra)
    $turnPath=Join-Path $script:cache 'current-turn.yaml'
    $script:result.cases += [ordered]@{name=$Name;return=$Return;calls=@($script:calls);currentTurn=if(Test-Path $turnPath){Read-McpYamlObject -Path $turnPath}else{$null};receipt=$script:LastReplPersistenceDetails;queue=@(Get-ChildItem $script:queue -File | ForEach-Object {[ordered]@{name=$_.Name;contents=Read-McpYamlObject -Path $_.FullName}});extra=$Extra}
}
foreach($verb in @('updateTurn','appendActions','appendDialog','completeTurn','failTurn','setTurnTitle')){
    New-HvCase -Name ('mismatch-'+$verb) -Persisted
    $payload=[ordered]@{requestId='req-OTHER';queryTitle='wrong caller title';response='wrong caller response';errorMessage='wrong caller failure';actions=@(@{type='design_decision';description='wrong caller action'});dialogItems=@(@{role='model';content='wrong caller dialog'})}
    $before=(Get-FileHash (Join-Path $script:cache 'current-turn.yaml')).Hash
    $fn='Invoke-Workflow'+$verb.Substring(0,1).ToUpperInvariant()+$verb.Substring(1)
    $ok=& $fn -ParamsYaml (ConvertTo-Yaml -Data $payload -Options WithIndentedSequences)
    $after=if(Test-Path (Join-Path $script:cache 'current-turn.yaml')){(Get-FileHash (Join-Path $script:cache 'current-turn.yaml')).Hash}else{'deleted'}
    Add-HvCase -Name ('mismatch-'+$verb) -Return $ok -Extra @{beforeHash=$before;afterHash=$after}
}
foreach($verb in @('updateTurn','appendActions','completeTurn')){
    foreach($metaMode in @('explicit','cache','none')){
        New-HvCase -Name ('metadata-'+$verb+'-'+$metaMode) -NoMetadata:($metaMode -eq 'none') -Degraded
